from __future__ import annotations


def merge_profile(record, profile):
    merged = dict(record)
    profile = profile or {}
    # Request values take precedence, but absent and null values are both
    # eligible for enrichment from the profile service.
    for field_name in ("timezone", "currency"):
        if merged.get(field_name) is None and profile.get(field_name) is not None:
            merged[field_name] = profile[field_name]
    return merged

