import json
from pathlib import Path
from collections.abc import Mapping

from fallback_policy import fill_system_defaults
from mock_profile_api import TRACE as PROFILE_TRACE, get_profile
from mock_transaction_api import TRACE as TX_TRACE, send_transaction
from normalization_policy import normalize_currency
from profile_merge import merge_profile
from transaction_contract import REQUIRED_FIELDS


def validate_record(record):
    if not isinstance(record, Mapping):
        return list(REQUIRED_FIELDS)
    missing = [
        field_name
        for field_name in REQUIRED_FIELDS
        if field_name not in record or record[field_name] is None
    ]
    return missing


def enrich(record):
    try:
        profile = get_profile(record["user_id"])
    except KeyError:
        # A missing profile is an expected enrichment miss.  The fallback
        # policy below supplies the fields required by the target API.
        profile = None
    merged = merge_profile(record, profile)
    return fill_system_defaults(merged)


def normalize(record):
    return normalize_currency(record)


def process_transactions(path):
    PROFILE_TRACE.clear()
    TX_TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    results = []
    rejected = []
    dispatchable = []
    for index, record in enumerate(payload):
        missing = validate_record(record)
        if missing:
            rejected.append({
                "index": index,
                "record": record,
                "errors": [
                    {
                        "field": field_name,
                        "reason": "required field is missing",
                        "observed": (
                            record.get(field_name)
                            if isinstance(record, Mapping)
                            else None
                        ),
                        "expected": "present and non-null",
                    }
                    for field_name in missing
                ],
            })
            continue
        dispatchable.append((index, record))

    # Do not start enrichment or dispatch until every input row has passed
    # local validation.
    for _index, record in dispatchable:
        enriched = enrich(record)
        normalized = normalize(enriched)
        results.append(send_transaction(normalized))
    return {
        "results": results,
        "profile_trace": list(PROFILE_TRACE),
        "tx_trace": list(TX_TRACE),
        "rejected": rejected,
        "counts": {
            "total": len(payload),
            "succeeded": len(results),
            "rejected": len(rejected),
        },
    }
